"""Small fix: gives the 3D box and the map a fixed size and redraws them after the page loads.
Run once from the src folder:   python fix_3d.py"""
import os
FILES = {
    'templates/detail.html': '{% extends "base.html" %}\n{% block title %}Design details · Intze Tank Platform{% endblock %}\n{% block content %}\n<section class="printable">\n  <div class="noprint"><a class="note" href="javascript:history.back()">← back to the options</a></div>\n  <h2>{{ n }} columns, M{{ grade }}</h2>\n  <p class="sub">Capacity {{ \'%.0f\'|format(vals.capacity_kl) }} kL · staging {{ \'%.1f\'|format(vals.staging_height_m) }} m · wind {{ \'%.0f\'|format(vals.wind_speed_m_s) }} m/s · seismic factor {{ vals.seismic_zone_factor }} · soil {{ \'%.0f\'|format(vals.soil_bearing_kpa) }} kPa · relative cost {{ \'%.1f\'|format(cost) }}</p>\n\n  {% if slender %}<div class="alert"><b>Not valid as shown.</b> {{ slender[0] }}</div>{% endif %}\n  {% for w in out.warnings if \'Slenderness\' not in w %}<div class="alert"><b>Note.</b> {{ w }}</div>{% endfor %}\n\n  <div class="card noprint" style="padding:8px">\n    <div id="tank3d" class="plot3d" role="img" aria-label="3D model of the tank"><p class="note plot-fallback">Loading the 3D model… If nothing appears, your browser may have 3D (WebGL) turned off; the numbers below are still complete.</p></div>\n  </div>\n  <p class="note noprint">Drag to rotate, scroll to zoom. A schematic: column positions and bracing are illustrative.</p>\n\n  <div class="grid g2" style="margin-top:28px">\n    {% for title, items in sections %}\n    <div class="card">\n      <h3 style="margin-bottom:14px">{{ title }}</h3>\n      <table class="kv">\n        {% for label, val, unit in items %}<tr><td>{{ label }}</td><td>{{ val }} {{ unit }}</td></tr>{% endfor %}\n      </table>\n    </div>\n    {% endfor %}\n  </div>\n\n  <div class="card" style="margin-top:16px">\n    <h3 style="margin-bottom:14px">Assumptions used for this design</h3>\n    <ul class="assump">{% for a in out.assumptions %}<li>{{ a }}</li>{% endfor %}</ul>\n  </div>\n  <p class="note" style="margin-top:18px">Decision-support only. Costs are relative (illustrative), wind and seismic use simplified static methods, and several members (ring beam, cone, raft, bracing) use placeholder rules. A licensed structural engineer must check and sign off any design before use.</p>\n  <p class="noprint" style="margin-top:24px"><button class="btn primary" type="button" onclick="window.print()">Print or save as PDF</button></p>\n</section>\n<script src="{{ url_for(\'vendor_plotly\') }}"></script>\n<script>\n  var fig = {{ fig_json|safe }};\n  fig.layout.autosize = true;\n  delete fig.layout.height;\n  var box = document.getElementById(\'tank3d\');\n  function draw() {\n    box.innerHTML = \'\';\n    Plotly.newPlot(box, fig.data, fig.layout, {responsive: true, displaylogo: false});\n  }\n  window.addEventListener(\'load\', function () {\n    draw();\n    setTimeout(function () { Plotly.Plots.resize(box); }, 300);\n    setTimeout(function () { Plotly.Plots.resize(box); }, 1200);\n  });\n</script>\n{% endblock %}\n',
    'templates/regional.html': '{% extends "base.html" %}\n{% block title %}Regional · Intze Tank Platform{% endblock %}\n{% block content %}\n<section>\n  <h2>Regional planner</h2>\n  <p class="sub">Give the villages or zones of an area. The planner forecasts demand, sizes storage at one third of daily demand, tries every way of grouping the zones into tanks, designs each tank with the real engine, and shows the cheapest arrangement. The zones below are demonstration data, not a real district.</p>\n  <form class="card" method="post" action="{{ url_for(\'regional\') }}">\n    <input type="hidden" name="csrf" value="{{ csrf_token() }}">\n    <div class="field"><label for="zones">Zones (CSV, at most 8). Columns: name, lat, lon, population (or area_km2 + density_per_km2), lpcd, growth_rate_pct, optional soil_bearing_kpa, wind_speed_m_s, seismic_zone_factor, polygon</label>\n      <textarea id="zones" name="zones" rows="9" spellcheck="false">{{ text }}</textarea></div>\n    <button class="btn primary" type="submit">Plan the tanks</button>\n  </form>\n</section>\n\n{% if result %}\n<section>\n  <h2>Cheapest arrangement: {{ result.best.k }} tank{{ \'s\' if result.best.k > 1 }}</h2>\n  <p class="sub">Total relative cost {{ \'%.0f\'|format(result.total) }} (tank structures {{ \'%.0f\'|format(result.best.tank_cost) }} + site overhead {{ \'%.0f\'|format(result.overhead * result.best.k) }} + distribution proxy {{ \'%.0f\'|format(result.best.dist_cost) }}). Design year +{{ result.years }} years, storage {{ \'%.2f\'|format(result.frac) }} × daily demand, service radius {{ result.radius }} km.</p>\n  <div class="card" style="padding:8px"><div id="map" class="plot2d" role="img" aria-label="Map of zones and tanks"></div></div>\n  {% for t in result.tanks %}\n  <div class="card opt" style="margin-top:14px">\n    <div>\n      <h3>Tank {{ t.no }}: {{ t.cap }} kL <em>serves {{ t.serves }}</em></h3>\n      <p>Needs {{ \'%.0f\'|format(t.need) }} kL · staging {{ t.staging }} m · farthest zone {{ \'%.2f\'|format(t.far) }} km</p>\n      <p>{{ t.d.n }} columns, M{{ t.d.grade }}, column dia {{ \'%.0f\'|format(t.d.col_dia) }} mm, tank dia {{ \'%.1f\'|format(t.d.diameter) }} m, {{ t.d.foundation|replace(\'_\', \' \') }}, extra load {{ \'%.0f\'|format(t.d.axial) }} kN per column ({{ t.d.case }} governs), concrete {{ \'%.0f\'|format(t.d.volume) }} m³{% if t.d.slender_warn %} · <b>slenderness limit exceeded: add bracing tiers</b>{% endif %}</p>\n    </div>\n  </div>\n  {% endfor %}\n</section>\n\n<section class="grid g2">\n  <div class="card">\n    <h3 style="margin-bottom:14px">Zones and demand</h3>\n    <table class="kv">\n      <tr><td><b>zone</b></td><td><b>design pop.</b></td><td><b>kL/day</b></td><td><b>storage kL</b></td></tr>\n      {% for z in result.zones %}<tr><td>{{ z.name }}</td><td>{{ \'{:,.0f}\'.format(z.design_pop) }}</td><td>{{ \'{:,.0f}\'.format(z.demand_kl_day) }}</td><td>{{ \'{:,.0f}\'.format(z.storage_kl) }}</td></tr>{% endfor %}\n    </table>\n  </div>\n  <div class="card">\n    <h3 style="margin-bottom:14px">Best for each number of tanks</h3>\n    <table class="kv">\n      <tr><td><b>tanks</b></td><td><b>total</b></td><td><b>structures</b></td><td><b>overhead</b></td></tr>\n      {% for r in result.by_k %}<tr><td>{{ r.k }}{% if r.best %} ← cheapest{% endif %}</td><td>{{ \'%.0f\'|format(r.total) }}</td><td>{{ \'%.0f\'|format(r.tank) }}</td><td>{{ \'%.0f\'|format(r.oh) }}</td></tr>{% endfor %}\n    </table>\n    <h3 style="margin:22px 0 10px">How much the answer depends on site overhead</h3>\n    <p class="note">Overhead is an illustrative number. If the cheapest tank count changes as it changes, the answer is not robust.</p>\n    <table class="kv">\n      {% for s in result.sens %}<tr><td>overhead {{ s.oh }}</td><td>{{ s.k }} tank{{ \'s\' if s.k > 1 }}, total {{ \'%.0f\'|format(s.total) }}</td></tr>{% endfor %}\n    </table>\n  </div>\n</section>\n<script src="{{ url_for(\'vendor_plotly\') }}"></script>\n<script>\n  var fig = {{ result.fig_json|safe }};\n  fig.layout.autosize = true;\n  window.addEventListener(\'load\', function () {\n    Plotly.newPlot(\'map\', fig.data, fig.layout, {responsive: true, displaylogo: false});\n    setTimeout(function () { Plotly.Plots.resize(document.getElementById(\'map\')); }, 300);\n  });\n</script>\n{% endif %}\n{% endblock %}\n',
    'static/style.css': '/* Intze Tank Platform -- dark, thin-type look based on the student\'s reference.\n   One accent (rose) is used for state and primary actions only. */\n:root {\n  --ink: #0c0c0e;\n  --panel: #141417;\n  --raised: #1b1b20;\n  --line: #2c2c33;\n  --line-soft: #202026;\n  --text: #edebe7;\n  --muted: #9a9aa4;\n  --accent: #e8556d;\n  --accent-soft: rgba(232, 85, 109, .14);\n  --good: #8fd6b4;\n  --warn: #f0b765;\n  --radius: 22px;\n  --display: "Outfit", "Segoe UI", system-ui, sans-serif;\n  --serif: "Instrument Serif", "Georgia", serif;\n}\n\n* { box-sizing: border-box; }\nhtml { color-scheme: dark; }\nbody {\n  margin: 0;\n  background: var(--ink);\n  color: var(--text);\n  font-family: var(--display);\n  font-weight: 300;\n  font-size: 17px;\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n}\na { color: inherit; }\nbutton, input, select { font: inherit; color: inherit; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 6px; }\n\n/* ---------- top bar ---------- */\n.bar {\n  display: flex; align-items: center; justify-content: space-between; gap: 24px;\n  padding: 22px clamp(20px, 4vw, 56px);\n  border-bottom: 1px solid var(--line-soft);\n}\n.brand { font-weight: 400; letter-spacing: .02em; text-decoration: none; font-size: 18px; }\n.brand span { font-family: var(--serif); font-style: italic; font-size: 22px; color: var(--muted); margin-left: 6px; }\n.nav { display: flex; gap: clamp(14px, 3vw, 40px); }\n.nav a {\n  text-decoration: none; font-size: 13px; letter-spacing: .14em; text-transform: uppercase;\n  color: var(--muted); padding: 6px 2px; border-bottom: 1px solid transparent;\n}\n.nav a:hover { color: var(--text); }\n.nav a[aria-current="page"] { color: var(--text); border-bottom-color: var(--accent); }\n.who { display: flex; align-items: center; gap: 14px; font-size: 14px; color: var(--muted); }\n.who b { font-weight: 400; color: var(--text); }\n.who form { margin: 0; }\n\n/* ---------- layout ---------- */\n.wrap { max-width: 1240px; margin: 0 auto; padding: clamp(28px, 5vw, 72px) clamp(20px, 4vw, 56px) 96px; }\nh1, h2, h3 { font-weight: 200; margin: 0; letter-spacing: .01em; line-height: 1.05; }\nh2 { font-size: clamp(30px, 4vw, 46px); margin-bottom: 8px; }\nh3 { font-size: 22px; font-weight: 300; line-height: 1.25; }\n.sub { color: var(--muted); max-width: 62ch; margin: 0 0 32px; }\nsection + section { margin-top: clamp(48px, 7vw, 96px); }\n\n.card {\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  background: linear-gradient(180deg, #17171b 0%, #101013 100%);\n  padding: 28px;\n}\n.grid { display: grid; gap: 16px; }\n.g3 { grid-template-columns: repeat(3, 1fr); }\n.g2 { grid-template-columns: repeat(2, 1fr); }\n@media (max-width: 880px) { .g3, .g2 { grid-template-columns: 1fr; } .nav { display: none; } }\n\n/* ---------- hero (overview) ---------- */\n.hero { display: grid; grid-template-columns: 1.3fr 1fr; gap: 32px; align-items: center; }\n@media (max-width: 880px) { .hero { grid-template-columns: 1fr; } }\n.big {\n  font-size: clamp(88px, 15vw, 210px); font-weight: 100; line-height: .9; letter-spacing: -.02em;\n}\n.big small { font-size: .32em; font-weight: 200; letter-spacing: 0; }\n.accent-serif { font-family: var(--serif); font-style: italic; font-weight: 400; color: var(--muted); font-size: clamp(30px, 4vw, 52px); margin-left: 10px; }\n.ring { width: min(100%, 300px); justify-self: end; }\n.ring circle { fill: none; stroke-width: 3; }\n.ring .track { stroke: var(--line); }\n.ring .fill { stroke: var(--accent); stroke-linecap: round; transform: rotate(-90deg); transform-origin: 50% 50%;\n  animation: draw 1.4s cubic-bezier(.2,.7,.2,1) both; }\n@keyframes draw { from { stroke-dashoffset: var(--len); } }\n@media (prefers-reduced-motion: reduce) { .ring .fill { animation: none; } }\n.ring text { fill: var(--muted); font-family: var(--display); font-size: 9px; font-weight: 300; }\n\n/* ---------- stage cards ---------- */\n.stage { display: flex; flex-direction: column; gap: 14px; min-height: 150px; }\n.stage .top { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }\n.stage .pct { font-size: 38px; font-weight: 200; }\n.meter { height: 2px; background: var(--line); border-radius: 2px; overflow: hidden; margin-top: auto; }\n.meter i { display: block; height: 100%; background: var(--accent); }\n.tag { font-size: 13px; color: var(--muted); border: 1px solid var(--line); border-radius: 99px; padding: 2px 10px; white-space: nowrap; }\n.tag.locked { color: var(--warn); border-color: rgba(240,183,101,.4); }\n\n/* ---------- facts ---------- */\n.facts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 22px 28px; margin: 18px 0 0; }\n.facts dt { color: var(--muted); font-size: 14px; }\n.facts dd { margin: 0; font-size: 26px; font-weight: 200; }\n\n/* ---------- log ---------- */\n.log { list-style: none; margin: 0; padding: 0; }\n.log li { display: grid; grid-template-columns: 150px 1fr; gap: 16px; padding: 14px 0; border-bottom: 1px solid var(--line-soft); }\n.log li:last-child { border-bottom: 0; }\n.log time { color: var(--muted); font-size: 14px; }\n@media (max-width: 640px) { .log li { grid-template-columns: 1fr; gap: 2px; } }\n\n/* ---------- forms ---------- */\nlabel { display: block; font-size: 14px; color: var(--muted); margin-bottom: 6px; }\ninput[type=text], input[type=password], input[type=number], select {\n  width: 100%; background: transparent; border: 1px solid var(--line); border-radius: 14px;\n  padding: 12px 16px; font-weight: 300;\n}\nselect option { background: var(--panel); }\ninput:disabled, select:disabled { opacity: .45; cursor: not-allowed; }\n.field { margin-bottom: 16px; }\n.row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n.btn {\n  display: inline-flex; align-items: center; gap: 10px; cursor: pointer;\n  border: 1px solid var(--text); background: transparent; border-radius: 99px; padding: 11px 26px;\n  font-weight: 400; letter-spacing: .02em;\n}\n.btn:hover { background: var(--text); color: var(--ink); }\n.btn.primary { border-color: var(--accent); background: var(--accent); color: #1a0509; }\n.btn.primary:hover { background: #f2748a; border-color: #f2748a; color: #1a0509; }\n.btn.quiet { border-color: var(--line); color: var(--muted); padding: 7px 18px; font-size: 14px; }\n.btn.quiet:hover { color: var(--ink); }\n.btn:disabled { opacity: .4; cursor: not-allowed; }\n.note { color: var(--muted); font-size: 14px; }\n.lockbox { border: 1px dashed var(--line); border-radius: var(--radius); padding: 22px 28px; color: var(--muted); }\n.lockbox b { color: var(--text); font-weight: 400; }\n\n.flash { border-radius: 14px; padding: 12px 18px; margin-bottom: 28px; border: 1px solid var(--line); }\n.flash.ok { border-color: rgba(143,214,180,.45); color: var(--good); }\n.flash.error { border-color: rgba(232,85,109,.55); color: #ff9aab; }\n\n/* ---------- advice ---------- */\n.alert { border-left: 2px solid var(--accent); padding: 4px 0 4px 20px; margin-bottom: 18px; }\n.alert b { font-weight: 400; }\n.opt { display: grid; grid-template-columns: 1fr auto; gap: 18px; align-items: center; }\n.opt + .opt { margin-top: 14px; }\n.opt h3 em { font-family: var(--serif); font-style: italic; color: var(--muted); font-weight: 400; }\n.opt p { margin: 6px 0 0; color: var(--muted); font-size: 15px; }\n@media (max-width: 640px) { .opt { grid-template-columns: 1fr; } }\n\n/* ---------- login ---------- */\nbody.login {\n  min-height: 100vh;\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 0%, #26262d 0%, rgba(12,12,14,0) 70%),\n    var(--ink);\n}\n.login main { max-width: 1100px; margin: 0 auto; padding: clamp(40px, 9vh, 110px) 24px 80px; text-align: center; }\n.login h1 { font-size: clamp(40px, 8vw, 104px); font-weight: 200; letter-spacing: .06em; text-transform: uppercase; line-height: 1.02; }\n.login h1 .serif { display: block; text-transform: none; letter-spacing: 0; font-family: var(--serif); font-style: italic; font-weight: 400; color: var(--muted); font-size: 1.05em; }\n.login .lede { color: var(--muted); max-width: 52ch; margin: 28px auto 48px; }\n.panel { max-width: 420px; margin: 0 auto; text-align: left; }\n.roles { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-top: 28px; }\n.demo { max-width: 420px; margin: 22px auto 0; font-size: 14px; color: var(--muted); text-align: left; }\n.demo table { width: 100%; border-collapse: collapse; margin-top: 8px; }\n.demo td { padding: 6px 0; border-bottom: 1px solid var(--line-soft); }\n.demo td:last-child { text-align: right; font-variant-numeric: tabular-nums; }\n\n.center-page { text-align: center; padding-top: 12vh; }\n.center-page h1 { font-size: clamp(40px, 7vw, 84px); }\n\n/* ---------- tables, text areas, print ---------- */\ntextarea { width: 100%; background: transparent; border: 1px solid var(--line); border-radius: 14px; padding: 12px 16px;\n  font-family: ui-monospace, Consolas, monospace; font-size: 14px; color: inherit; }\n.kv { width: 100%; border-collapse: collapse; }\n.kv td { padding: 8px 0; border-bottom: 1px solid var(--line-soft); vertical-align: top; }\n.kv td:last-child { text-align: right; font-variant-numeric: tabular-nums; }\n.assump { margin: 0; padding-left: 20px; color: var(--muted); font-size: 15px; }\n.assump li { margin-bottom: 8px; }\n.opt .btn { white-space: nowrap; }\n@media print {\n  html { color-scheme: light; }\n  body { background: #fff; color: #111; font-size: 12pt; }\n  .bar, .noprint, .flash { display: none !important; }\n  .card { background: #fff; border: 1px solid #bbb; break-inside: avoid; padding: 14px; }\n  .sub, .note, .assump, .kv td { color: #222; }\n  h2, h3 { color: #000; }\n  .wrap { padding: 0; max-width: none; }\n}\n\n.plot3d { width: 100%; height: 640px; min-height: 640px; background: #fff; border-radius: 14px; overflow: hidden; }\n.plot2d { width: 100%; height: 700px; min-height: 700px; background: #fff; border-radius: 14px; overflow: hidden; }\n.plot-fallback { color: #444; padding: 24px; }\n@media print { .plot3d, .plot2d { display: none; } }\n',
}
for path, text in FILES.items():
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("written:", path)
print("Done. Now run:  python test_app.py")
